// ============================================================
// Cloudflare Worker – Batch File Sharing (KV only)  [DEBUGGED]
//
// Fixes applied (vs. the version you posted):
//   1. KV value size: lowered per-file cap to 18MB so the
//      base64-encoded payload + JSON wrapper stays under
//      KV's hard 25MB-per-value limit.
//   2. XSS in attributes: escapeHtml() now also escapes " and '.
//   3. expires_at now uses a single createdAt timestamp across
//      both file and batch metadata (was inconsistent before).
//   4. Added explicit "never" case to the expiry switch.
//   5. base64 → bytes decode now masks with `& 0xFF` for safety.
//   6. ArrayBuffer → base64 uses chunked apply() for ~5-10× speedup.
//   7. Content-Disposition follows RFC 6266 / 5987 for unicode names.
//   8. All responses now carry consistent CORS headers.
//   9. notFoundHtml served with charset=utf-8 (was missing).
//  10. Top-level try/catch in fetch handler so unhandled errors
//      return 500 instead of crashing the worker.
//  11. Trailing slashes in batch/view/raw/download paths normalized.
//  12. Client-side MAX_SIZE aligned with the new 18MB server cap.
//
// Required bindings:
//   - KV namespace `FILES`
//
// Notes:
//   - KV is *not* ideal for binary blobs. For serious file hosting
//     migrate to R2. This worker keeps the design KV-only as you
//     requested — the 18MB cap reflects that constraint.
//   - KV free tier gives you 100MB of total storage; a single
//     18MB file uses ~24MB of that.
// ============================================================

export default {
  async fetch(request, env, ctx) {
    try {
      return await route(request, env);
    } catch (err) {
      console.error("Unhandled error:", err);
      return new Response(
        "Internal Server Error: " + (err && err.message ? err.message : "unknown"),
        { status: 500, headers: { "Content-Type": "text/plain; charset=utf-8" } }
      );
    }
  },
};

// =================== Router ===================

async function route(request, env) {
  const url = new URL(request.url);
  let { pathname } = url;

  // Normalize trailing slash (except root)
  if (pathname.length > 1 && pathname.endsWith("/")) {
    pathname = pathname.slice(0, -1);
  }

  const baseUrl = getBaseUrl(request, url);

  // ---- CORS preflight ----
  if (request.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders() });
  }

  // ---- Upload interface ----
  if (pathname === "/" || pathname === "/upload") {
    return htmlResponse(HTML_UPLOAD);
  }

  // ---- Multi-file upload API ----
  if (pathname === "/api/upload" && request.method === "POST") {
    return await handleUpload(request, env, baseUrl);
  }

  // ---- Batch page ----
  if (pathname.startsWith("/batch/")) {
    const batchId = pathname.slice(7);
    if (!batchId) return new Response("Invalid batch ID", { status: 400 });
    return await handleBatchPage(env, batchId, baseUrl);
  }

  // ---- Preview page ----
  if (pathname.startsWith("/view/")) {
    const fileId = pathname.slice(6);
    if (!fileId) return new Response("Invalid file ID", { status: 400 });
    return await handlePreviewPage(env, fileId, baseUrl);
  }

  // ---- Raw file (inline) ----
  if (pathname.startsWith("/raw/")) {
    const fileId = pathname.slice(5);
    if (!fileId) return new Response("Invalid file ID", { status: 400 });
    return await handleRawFile(env, fileId, "inline");
  }

  // ---- Download file (attachment) ----
  if (pathname.startsWith("/download/")) {
    const fileId = pathname.slice(10);
    if (!fileId) return new Response("Invalid file ID", { status: 400 });
    return await handleRawFile(env, fileId, "attachment");
  }

  return new Response("Not found", { status: 404, headers: corsHeaders() });
}

// =================== Handlers ===================

async function handleUpload(request, env, baseUrl) {
  try {
    const formData = await request.formData();
    const files = formData
      .getAll("file")
      .filter((f) => f && typeof f.name === "string" && f.name);
    const expiryOption = String(formData.get("expiry") || "7days");

    if (files.length === 0) {
      return jsonResponse({ error: "No files uploaded." }, 400);
    }

    // KV value hard limit: 25MB. Base64 adds ~33%, JSON wrapper
    // adds a little more. 18MB raw → ~24MB stored → safe.
    const maxSize = 18 * 1024 * 1024;

    let expiryTTL = null;
    let expiryDays = 0;
    switch (expiryOption) {
      case "1day":   expiryTTL = 86400;   expiryDays = 1;  break;
      case "7days":  expiryTTL = 604800;  expiryDays = 7;  break;
      case "30days": expiryTTL = 2592000; expiryDays = 30; break;
      case "never":  expiryTTL = null;    expiryDays = 0;  break;
      default:       expiryTTL = 604800;  expiryDays = 7;  break;
    }

    const batchId = crypto.randomUUID();
    const createdAt = Date.now();
    const batchFiles = [];
    const errors = [];

    for (const file of files) {
      const fileName = file.name;
      const fileType = file.type || "application/octet-stream";
      const fileSize = file.size;

      if (fileSize > maxSize) {
        errors.push({
          name: fileName,
          error: `File exceeds ${maxSize / 1024 / 1024}MB limit`,
        });
        continue;
      }

      try {
        const bytes = await file.arrayBuffer();
        const base64Data = arrayBufferToBase64(bytes);
        const id = crypto.randomUUID();

        const fileData = {
          id,
          batch_id: batchId,
          name: fileName,
          type: fileType,
          size: fileSize,
          created_at: createdAt,
          expiry_option: expiryOption,
          expiry_days: expiryDays,
          expires_at: expiryTTL ? createdAt + expiryDays * 86400000 : null,
          data: base64Data,
        };

        const fileKey = `file:${id}`;
        if (expiryTTL) {
          await env.FILES.put(fileKey, JSON.stringify(fileData), {
            expirationTtl: expiryTTL,
          });
        } else {
          await env.FILES.put(fileKey, JSON.stringify(fileData));
        }

        const ext = fileName.split(".").pop().toLowerCase();
        batchFiles.push({
          id,
          previewUrl: `${baseUrl}/view/${id}`,
          rawUrl: `${baseUrl}/raw/${id}`,
          downloadUrl: `${baseUrl}/download/${id}`,
          fileName,
          fileSize: formatFileSize(fileSize),
          fileType,
          icon: getFileIcon(ext),
          expiryDays,
          expiryText: expiryDays === 0 ? "Never expires" : `${expiryDays} days`,
        });
      } catch (err) {
        console.error("File processing error:", err);
        errors.push({ name: fileName, error: err.message || "Upload failed" });
      }
    }

    // Batch metadata — uses the same `createdAt` as the files
    const batchData = {
      id: batchId,
      files: batchFiles.map((f) => ({
        id: f.id,
        name: f.fileName,
        size: f.fileSize,
        type: f.fileType,
        icon: f.icon,
      })),
      created_at: createdAt,
      expiry_option: expiryOption,
      expiry_days: expiryDays,
      expires_at: expiryTTL ? createdAt + expiryDays * 86400000 : null,
    };

    const batchKey = `batch:${batchId}`;
    if (expiryTTL) {
      await env.FILES.put(batchKey, JSON.stringify(batchData), {
        expirationTtl: expiryTTL,
      });
    } else {
      await env.FILES.put(batchKey, JSON.stringify(batchData));
    }

    return jsonResponse({
      success: errors.length === 0,
      uploaded: batchFiles.length,
      failed: errors.length,
      batchId,
      batchUrl: `${baseUrl}/batch/${batchId}`,
      files: batchFiles,
      errors,
    });
  } catch (err) {
    console.error("Upload error:", err);
    return jsonResponse({ error: err.message || "Upload failed" }, 500);
  }
}

async function handleBatchPage(env, batchId, baseUrl) {
  try {
    const raw = await env.FILES.get(`batch:${batchId}`);
    if (!raw) return htmlResponse(notFoundHtml, 404);
    const batchData = JSON.parse(raw);

    if (batchData.expires_at && Date.now() > batchData.expires_at) {
      await env.FILES.delete(`batch:${batchId}`);
      return new Response("Batch expired", { status: 410 });
    }

    return htmlResponse(generateBatchPage(batchData, baseUrl));
  } catch (err) {
    console.error("Batch page error:", err);
    return new Response("Error loading batch", { status: 500 });
  }
}

async function handlePreviewPage(env, fileId, baseUrl) {
  try {
    const raw = await env.FILES.get(`file:${fileId}`);
    if (!raw) return htmlResponse(notFoundHtml, 404);
    const fileData = JSON.parse(raw);

    if (fileData.expires_at && Date.now() > fileData.expires_at) {
      await env.FILES.delete(`file:${fileId}`);
      return new Response("File expired", { status: 410 });
    }

    const isText =
      (fileData.type && fileData.type.startsWith("text/")) ||
      /\.(txt|md|json|js|html|css|xml|csv|yml|yaml|ts|tsx|jsx|vue|py|sh|bash|ini|toml|log)$/i.test(
        fileData.name
      );

    let rawText = null;
    if (isText) {
      const bytes = base64ToBytes(fileData.data);
      rawText = new TextDecoder("utf-8").decode(bytes);
    }

    return htmlResponse(generatePreviewPage(fileData, isText, rawText, baseUrl));
  } catch (err) {
    console.error("Preview error:", err);
    return new Response("Error loading preview", { status: 500 });
  }
}

async function handleRawFile(env, fileId, disposition) {
  try {
    const raw = await env.FILES.get(`file:${fileId}`);
    if (!raw) return new Response("Not found", { status: 404 });
    const fileData = JSON.parse(raw);

    if (fileData.expires_at && Date.now() > fileData.expires_at) {
      await env.FILES.delete(`file:${fileId}`);
      return new Response("File expired", { status: 410 });
    }

    const bytes = base64ToBytes(fileData.data);

    const headers = {
      "Content-Type": fileData.type || "application/octet-stream",
      "Content-Disposition": contentDisposition(fileData.name, disposition),
      "Content-Length": fileData.size.toString(),
      ...corsHeaders(),
    };
    if (disposition === "inline") {
      headers["Cache-Control"] = "public, max-age=3600";
    }

    return new Response(bytes, { headers });
  } catch (err) {
    console.error(`${disposition} error:`, err);
    return new Response("Error", { status: 500 });
  }
}

// =================== Helpers ===================

function arrayBufferToBase64(buffer) {
  const bytes = new Uint8Array(buffer);
  let binary = "";
  const chunk = 0x4000; // safely under any engine's arg limit
  for (let i = 0; i < bytes.length; i += chunk) {
    binary += String.fromCharCode.apply(null, bytes.subarray(i, i + chunk));
  }
  return btoa(binary);
}

function base64ToBytes(b64) {
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i) & 0xff;
  }
  return bytes;
}

function formatFileSize(bytes) {
  if (bytes < 1024) return bytes + " B";
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + " KB";
  return (bytes / (1024 * 1024)).toFixed(1) + " MB";
}

function getFileIcon(ext) {
  const icons = {
    jpg: "fa-file-image", jpeg: "fa-file-image", png: "fa-file-image", gif: "fa-file-image",
    webp: "fa-file-image", svg: "fa-file-image", bmp: "fa-file-image",
    pdf: "fa-file-pdf",
    txt: "fa-file-alt", md: "fa-file-alt", log: "fa-file-alt", rtf: "fa-file-alt",
    js: "fa-file-code", ts: "fa-file-code", jsx: "fa-file-code", tsx: "fa-file-code",
    html: "fa-file-code", css: "fa-file-code", scss: "fa-file-code", sass: "fa-file-code",
    json: "fa-file-code", xml: "fa-file-code", yml: "fa-file-code", yaml: "fa-file-code",
    py: "fa-file-code", java: "fa-file-code", c: "fa-file-code", cpp: "fa-file-code",
    h: "fa-file-code", hpp: "fa-file-code", sh: "fa-file-code", bash: "fa-file-code",
    zip: "fa-file-archive", rar: "fa-file-archive", "7z": "fa-file-archive",
    tar: "fa-file-archive", gz: "fa-file-archive", bz2: "fa-file-archive",
    mp4: "fa-file-video", mov: "fa-file-video", avi: "fa-file-video",
    mkv: "fa-file-video", webm: "fa-file-video", flv: "fa-file-video",
    mp3: "fa-file-audio", wav: "fa-file-audio", ogg: "fa-file-audio", flac: "fa-file-audio",
    doc: "fa-file-word", docx: "fa-file-word",
    xls: "fa-file-excel", xlsx: "fa-file-excel", csv: "fa-file-excel",
    ppt: "fa-file-powerpoint", pptx: "fa-file-powerpoint",
  };
  return icons[ext] || "fa-file";
}

// HTML-escape that also handles quote chars (prevents XSS in attributes)
function escapeHtml(str) {
  if (str == null) return "";
  return String(str).replace(/[&<>"']/g, (m) => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;",
  }[m]));
}

function corsHeaders() {
  return {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET, POST, DELETE, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type",
  };
}

function jsonResponse(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "Content-Type": "application/json", ...corsHeaders() },
  });
}

function htmlResponse(html, status = 200) {
  return new Response(html, {
    status,
    headers: { "Content-Type": "text/html; charset=utf-8", ...corsHeaders() },
  });
}

function getBaseUrl(request, url) {
  if (url.origin && url.origin !== "null") return url.origin;
  if (request) {
    const protocol = request.headers.get("X-Forwarded-Proto") || "https";
    const host = request.headers.get("Host") || "localhost";
    return `${protocol}://${host}`;
  }
  return "https://localhost";
}

// RFC 6266 / RFC 5987: handle non-ASCII filenames correctly
function contentDisposition(filename, disposition) {
  const asciiFallback = filename
    .replace(/[^\x20-\x7E]/g, "_")
    .replace(/["\\]/g, "_");
  const encoded = encodeURIComponent(filename);
  return `${disposition}; filename="${asciiFallback}"; filename*=UTF-8''${encoded}`;
}

// =================== HTML Templates ===================

const notFoundHtml = `<!DOCTYPE html>
<html lang="en">
<head>
<link rel="shortcut icon" href="data:image/png;base64," />
<meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>File Not Found · FileShare</title>
  <style>
    body { font-family: system-ui, -apple-system, sans-serif; text-align: center; padding: 50px;
           background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); min-height: 100vh;
           color: white; display: flex; flex-direction: column; align-items: center; justify-content: center; margin: 0; }
    h1 { font-size: 2.5rem; margin-bottom: 1rem; }
    p { font-size: 1.1rem; opacity: 0.9; margin-bottom: 2rem; }
    a { display: inline-block; padding: 0.75rem 1.5rem; background: white; color: #667eea;
        text-decoration: none; border-radius: 2rem; font-weight: 600; transition: transform 0.2s; }
    a:hover { transform: translateY(-2px); }
  </style>
</head>
<body>
  <h1>🔒 File Not Found or Expired</h1>
  <p>The file may have expired or been deleted.</p>
  <a href="/">Upload new files</a>
</body>
</html>`;

